import{z as o,x as n,o as e,c as p,q as t,j as A,D as E,d as i,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"利率期权的波动","description":"","frontmatter":{"title":"利率期权的波动","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-rate-vol.md","filePath":"quant/rc-rate-vol.md","lastUpdated":1791413859000}'),s={name:"quant/rc-rate-vol.md"};function d(c,a,f,C,m,h){const B=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="利率期权的波动" tabindex="-1">利率期权的波动 <a class="header-anchor" href="#利率期权的波动" aria-label="Permalink to &quot;利率期权的波动&quot;">​</a></h1><div class="epigraph"><p>利率波动率的期限结构是均值回复投在市场里的影子：回复越强、到期越长，利率能到达的范围越窄，长端波动率就被压得越低。</p><footer>—— 据 Andersen and Piterbarg, *Interest Rate Modeling*, 2010；Hull and White, *Review of Financial Studies*, 1990 整理</footer></div><p><a href="/quant/rc-swaption-deep">上一课</a>解剖了网格上的单点 Swaption：年金计价物、移位报价与日历价差。本课把视角拉远，看整张利率波动率曲面的结构与协同运动：cap 与 floor 的逐期波动、平值波动与远期波动的关系、期限结构的均值回复解释，以及曲面风险怎么映射进交易台的 vega 账本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>cap 是一串 caplet 的和：每个计息期有自己的远期利率 \\(f_i\\) 与自己的波动率，整只期权的价值是各期 \\(\\tau_i N (f_i - K)^+\\) 的期权值折现求和。市场却常报「flat vol」——整只 cap 一个数——而逐期对冲需要的是每期的 forward vol：用 flat vol 去对冲单期，vega 分布全错。更深的缺口在两个市场之间：caplet 剥离与 Swaption 校准给出的波动率历史上对不上，用一边校准的模型给另一边报价会产生系统性偏差；负利率时代正态坐标成为主流后，smile 的形状习惯也要重看。本课要回答：两层波动率为什么不一致、怎么处理，以及长端波动率为什么被均值回复压低。</p><p><span class="marginnote">flat vol 翻译一下：把一整只 cap（可能含几十个 caplet）用同一个波动率数字报价。方便成交，但各期真实的波动并不相同；拿这一个数去对冲某一期，vega 会错配。对冲单期前，要先用剥离法把 flat vol 拆成逐期 forward vol。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先分清三层「波动率」：caplet 层的逐期波动、cap 层的 flat 波动、Swaption 层的联合波动。三者之间没有恒等式：caplet 的标的是单个远期利率，Swaption 的标的是互换利率的加权平均，经典处理是 timing 与 convexity 调整，基础见 <a href="/quant/caps-floors-swaptions">caps / floors / swaptions</a>。曲面建模按切片走：每个「到期 × 期限」点用 SABR 描述 smile（校准细节见<a href="/quant/sabr-calib">SABR 校准</a>），翼部用受控外推防止负密度，见<a href="/quant/sabr-wing-extrap">SABR 翼部外推</a>。期限结构交给均值回复：Hull–White 类模型里 \\(r(T)\\) 的方差是 \\(\\frac{\\sigma^2}{2\\kappa}\\left(1-e^{-2\\kappa T}\\right)\\)，\\(\\kappa\\gt 0\\) 时方差有界，长到期波动率因此饱和而非线性增长；校准出的 \\(\\kappa\\) 同时控制百慕大行权价值与长端 vega，动它就是动两本账。风险管理上把曲面运动降维：水平、扭曲（短端到期对长端到期）、曲率三个 vega 桶，比逐点 vega 稳定，与<a href="/quant/vol-surface">波动率曲面</a>一课的分层同构。</p><p><span class="marginnote">数字实例：取 \\(\\sigma=1\\%\\)、\\(\\kappa=0.1\\)/年，方差饱和值 \\(\\sigma^2/(2\\kappa)=0.0005\\)，长端利率波动的天花板约 2.24%；\\(\\kappa\\) 翻倍到 0.2，天花板降到约 1.58%。回复越快，长端波动被压得越低——这就是波动率期限结构随到期平坦化下行的算术来源。</span></p>',9)),(e(),A(r,null,{default:E(()=>[l(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22caplet%20%E5%89%A5%E7%A6%BB%EF%BC%9A%E9%80%90%E6%9C%9F%E8%BF%9C%E6%9C%9F%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20FLAT%5B%22flat%20vol%20%E4%B8%8E%20timing%20%2F%20convexity%20%E8%B0%83%E6%95%B4%22%5D%0A%20%20SWP%5B%22swaption%20%E7%BD%91%E6%A0%BC%20smile%22%5D%20--%3E%20FIT%5B%22%E9%80%90%E7%82%B9%20SABR%20%2B%20%E7%BF%BC%E9%83%A8%E5%A4%96%E6%8E%A8%22%5D%0A%20%20FIT%20--%3E%20TERM%5B%22%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%EF%BC%9A%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%E5%8E%8B%E7%BC%A9%E9%95%BF%E7%AB%AF%22%5D%0A%20%20CAP%20--%3E%20CONS%7B%22%E4%B8%A4%E4%B8%AA%E5%B8%82%E5%9C%BA%E6%A0%A1%E5%87%86%E6%98%AF%E5%90%A6%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20SWP%20--%3E%20CONS%0A%20%20CONS%20--%3E%7C%22%E4%B8%8D%E4%B8%80%E8%87%B4%22%7C%20RES%5B%22%E8%AE%B0%E4%B8%BA%E6%A8%A1%E5%9E%8B%E9%A3%8E%E9%99%A9%EF%BC%8C%E4%B8%8D%E5%BC%BA%E8%A1%8C%E5%B9%B3%E5%9D%87%22%5D%0A%20%20CONS%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20RISK%5B%22vega%20%E5%88%86%E6%A1%B6%EF%BC%9A%E6%B0%B4%E5%B9%B3%20%2F%20%E6%89%AD%E6%9B%B2%20%2F%20%E6%9B%B2%E7%8E%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均值回复压低长端波动不是比喻而是公式：\\(\\kappa\\gt 0\\) 时 \\(r(T)\\) 的积分方差收敛到 \\(\\frac{\\sigma^2}{2\\kappa}\\)，波动率期限结构因此随到期平坦化下行。这个约束反过来限制了能校准出的曲面形状：若市场长端 Swaption 波动显著高于单因子模型允许的范围，说明单因子描述不足，要上双因子或局部-随机混合结构，参考<a href="/quant/local-stoch-vol">局部-随机混合模型</a>与 <a href="/quant/bergomi">Bergomi</a> 类多因子框架。caplet 与 Swaption 市场的系统性偏差是结构性的而非噪声：两个市场的参与者与对冲流不同，逐期 strips 的供需、抵押债权的期权化需求各自定价，把两边强行平均会同时错两本账。正态坐标下 smile 变得对称甚至反斜，移位对数正态是过渡期的折中——机制在上一课，这里是它在曲面上的投影。</p><p><span class="marginnote">Joshi and Rebonato（2003，<em>Quantitative Finance</em>）的移位扩散随机波动扩展与 Andersen–Andreasen 对 LMM 的移位扩展指向同一件事：负利率下正态坐标不是权宜，而是利率期权 smile 的自然坐标；对数正态 SABR 的 \\(\\beta=1\\) 在这里没有解释力。</span></p>',3)),(e(),A(r,null,{default:E(()=>[l(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%9B%9E%E5%A4%8D%E9%80%9F%E5%BA%A6%20kappa%20%E5%A4%A7%E4%BA%8E%200%22%5D%20--%3E%20VAR%5B%22r(T)%20%E6%96%B9%E5%B7%AE%E6%94%B6%E6%95%9B%E5%88%B0%20sigma%5E2%20%2F%202%20kappa%22%5D%0A%20%20VAR%20--%3E%20SAT%5B%22%E9%95%BF%E7%AB%AF%E6%B3%A2%E5%8A%A8%E9%A5%B1%E5%92%8C%E8%80%8C%E9%9D%9E%E7%BA%BF%E6%80%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20SAT%20--%3E%20FLAT%5B%22%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%E5%B9%B3%E5%9D%A6%E5%8C%96%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20HIGH%5B%22%E5%B8%82%E5%9C%BA%E9%95%BF%E7%AB%AF%E6%B3%A2%E5%8A%A8%E8%B6%85%E5%87%BA%E5%8D%95%E5%9B%A0%E5%AD%90%E4%B8%8A%E9%99%90%22%5D%20--%3E%20MORE%5B%22%E4%B8%8A%E5%8F%8C%E5%9B%A0%E5%AD%90%E6%88%96%E5%B1%80%E9%83%A8-%E9%9A%8F%E6%9C%BA%E6%B7%B7%E5%90%88%22%5D%0A%20%20TWO%5B%22caplet%20%E4%B8%8E%20swaption%20%E5%8F%82%E4%B8%8E%E8%80%85%E5%92%8C%E5%AF%B9%E5%86%B2%E6%B5%81%E4%B8%8D%E5%90%8C%22%5D%20--%3E%20BIAS%5B%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B7%AE%E6%98%AF%E7%BB%93%E6%9E%84%E6%80%A7%E7%9A%84%22%5D%0A%20%20BIAS%20--%3E%20AVG%5B%22%E5%BC%BA%E8%A1%8C%E5%B9%B3%E5%9D%87%E4%BC%9A%E5%90%8C%E6%97%B6%E9%94%99%E4%B8%A4%E6%9C%AC%E8%B4%A6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课讲结构与协同，不讲波动率交易策略与央行日程的博弈——那是波动率交易课程的范围。股票市场的 smile 工具不能整套搬来：<a href="/quant/svi-ssvi">SVI 与 SSVI</a> 在利率市场的适用性受正态坐标与负利率限制，参数约束要重推。曲面因子降维丢掉局部细节：央行会议日前短端到期的孤立凸起要单独列账，不能摊进三因子。最后，逐点完美拟合会造出不可对冲的 vega 抖动，光滑约束与拟合误差的取舍属于校准正则化问题，<a href="/quant/calibration-regularization">校准正则化</a>一课有专门处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cap 是 caplet 的和：flat vol 与 forward vol 是两层账，对冲单期必须用逐期波动。</li><li>caplet 与 Swaption 波动率来自两个市场，一致性要检验而非假设，不一致就是模型风险。</li><li>均值回复把长端波动率压向饱和值，期限结构的形状是 \\(\\kappa\\) 的影子。</li><li>曲面风险按水平、扭曲、曲率分桶管理，事件日的孤立凸起单独列账。</li><li>出处：Andersen and Piterbarg, <em>Interest Rate Modeling</em>, 2010；Hull and White, 1990；SABR 系列与校准正则化见本栏相应课程。</li></ul>',4))])}const S=o(s,[["render",d]]);export{_ as __pageData,S as default};
